import itertools

def is_kawaii(sequence):
    N = len(sequence)
    if N == 0:
        return True

    # 1. Determine the maximum element present
    M_actual = max(sequence)

    # 2. Check Condition 1 and Condition 2 for k = 2 to M_actual
    for k in range(2, M_actual + 1):
        # Check C1: If k appears, k-1 must appear
        if k in sequence:
            if (k - 1) not in sequence:
                return False

            # Check C2: First occurrence of k-1 comes before last occurrence of k

            # Find L_{k-1} (First occurrence of k-1)
            L_k_minus_1 = -1
            for i in range(N):
                if sequence[i] == (k - 1):
                    L_k_minus_1 = i
                    break

            # Find R_k (Last occurrence of k)
            R_k = -1
            for i in range(N - 1, -1, -1):
                if sequence[i] == k:
                    R_k = i
                    break

            # Indices are 0-based here. The condition is L_{k-1} < R_k.
            # If using 1-based indexing (standard problem style), this translates to the same comparison.
            if L_k_minus_1 >= R_k:
                return False

    return True

def count_kawaii_sequences(N, M_max):
    count = 0
    # Iterate over all possible sequences where elements are in {1, ..., M_max}
    elements = range(1, M_max + 1)

    # Generate all sequences of length N using elements from {1, ..., M_max}
    for seq_tuple in itertools.product(elements, repeat=N):
        sequence = list(seq_tuple)
        if is_kawaii(sequence):
            count += 1

    return count

