N_values = [3, 4, 5]
M_values = [1, 2, 3]

results = {}

for N in N_values:
    results[N] = {}
    print(f"--- N = {N} ---")
    for M in M_values:
        count = count_kawaii_sequences(N, M)
        results[N][M] = count
        print(f"Count for N={N}, M_max={M}: {count}")

print("\n--- Summary ---")
